// ==UserScript==
// @name         SPAS-12 + Mosin Sound Swap (Base64 Mode)
// @namespace    survev-sound-swap
// @version      4.0
// @description  Swap SPAS-12 and Mosin sounds using embedded Base64 audio.
// @match        *://localhost:5173/*
// @match        *://survev.io/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(() => {
    "use strict";
    const REPLACEMENTS = {
        "spas12_01":       "data:audio/mpeg;base64,",
        "spas12_cycle_01": "data:audio/mpeg;base64,",
        "spas12_reload_01":"data:audio/mpeg;base64,",
        "spas12_pull_01":  "data:audio/mpeg;base64,",


        "mosin_01":        "data:audio/mpeg;base64,",
        "mosin_cycle_01":  "data:audio/mpeg;base64,",
        "mosin_reload_01": "data:audio/mpeg;base64,",
        "mosin_reload_02": "data:audio/mpeg;base64,",
        "mosin_pull_01":   "data:audio/mpeg;base64,"
    };

    function getReplacementUrl(originalUrl) {
        if (typeof originalUrl !== 'string') return originalUrl;

        for (const [key, customUrl] of Object.entries(REPLACEMENTS)) {
            if (originalUrl.includes(key)) {
                console.log(`[Sound Mod] Intercepted and injected Base64: ${key}`);
                return customUrl;
            }
        }
        return originalUrl;
    }

    const originalFetch = window.fetch;
    window.fetch = async function(...args) {
        let resource = args[0];
        if (typeof resource === 'string') {
            args[0] = getReplacementUrl(resource);
        } else if (resource instanceof Request) {
            const newUrl = getReplacementUrl(resource.url);
            if (newUrl !== resource.url) {
                args[0] = new Request(newUrl, resource);
            }
        }
        return originalFetch.apply(this, args);
    };

    const originalXhrOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function(method, url, ...rest) {
        url = getReplacementUrl(url);
        return originalXhrOpen.call(this, method, url, ...rest);
    };

    const OriginalAudio = window.Audio;
    window.Audio = function(url) {
        if (url) {
            url = getReplacementUrl(url);
        }
        return new OriginalAudio(url);
    };
    window.Audio.prototype = OriginalAudio.prototype;

    console.log("[Sound Mod] Network interceptors with Base64 injected.");
})();
